  1	import type {
  2	  ParsedResponse,
  3	  Response,
  4	  ResponseCreateParamsBase,
  5	  ResponseStreamEvent,
  6	  ResponseTextConfig,
  7	} from '../../resources/responses/responses';
  8	import type { RequestOptions } from '../../internal/request-options';
  9	import type { ReadableStream } from '../../internal/shim-types';
 10	import { CancelReadableStream } from '../../internal/shims';
 11	import { APIPromise } from '../../core/api-promise';
 12	import { APIError, OpenAIError } from '../../error';
 13	import type OpenAI from '../../index';
 14	import { EventStream } from '../EventStream';
 15	import type { BaseEvents } from '../EventStream';
 16	import type { ResponseFunctionCallArgumentsDeltaEvent, ResponseTextDeltaEvent } from './EventTypes';
 17	import {
 18	  accumulateResponseWithContext,
 19	  cloneValidatedResponse,
 20	  createResponseContext,
 21	  hasRoutedOutputCallIdentity,
 22	  replaceResponseOutputItem,
 23	  validateResponseOutputItemIdentity,
 24	} from '../../internal/responses/response-accumulator';
 25	import { ensureCanonicalOutputText } from '../../internal/responses/canonical-output-text';
