 34	import { Stream } from '../../streaming';
 35	
 36	type EventField<Event> = Event extends unknown ? keyof Event : never;
 37	
 38	// Require every generated native event field here. Unknown hidden transport members remain private.
 39	const nativeEventFields: Record<EventField<ResponseStreamEvent>, true> = {
 40	  annotation: true,
 41	  annotation_index: true,
 42	  arguments: true,
 43	  background: true,
 44	  code: true,
 45	  command: true,
 46	  command_index: true,
 47	  content_index: true,
 48	  delta: true,
 49	  input: true,
 50	  item: true,
 51	  item_id: true,
 52	  logprobs: true,
 53	  message: true,
 54	  obfuscation: true,
 55	  output: true,
 56	  output_format: true,
 57	  output_index: true,
 58	  param: true,
 59	  part: true,
 60	  partial_image_b64: true,
 61	  partial_image_index: true,
 62	  quality: true,
 63	  refusal: true,
 64	  response: true,
 65	  sequence_number: true,
 66	  size: true,
 67	  status: true,
 68	  summary_index: true,
 69	  text: true,
 70	  type: true,
 71	};
 72	
 73	/** Parameters for starting a new response stream or replaying an existing response. */
 74	export type ResponseStreamParams = ResponseCreateAndStreamParams | ResponseStreamByIdParams;
 75	
 76	/** Response-creation parameters accepted by the streaming convenience helper. */
 77	export type ResponseCreateAndStreamParams = Omit<ResponseCreateParamsBase, 'stream'> &
 78	  ResponseParsingInput & {
 79	    /** Streaming is always enabled by the helper and may be specified explicitly. */
 80	    stream?: true;
 81	  };
 82	
 83	/** Parameters for replaying an existing response and optionally filtering emitted events. */
 84	export type ResponseStreamByIdParams = {
 85	  /**
 86	   * The ID of the response to stream.
 87	   */
 88	  response_id: string;
 89	  /**
 90	   * If provided, events with a sequence number less than or equal to this value
 91	   * will not be emitted. The helper still replays them internally to build a
 92	   * complete snapshot for later events and `finalResponse()`.
 93	   */
 94	  starting_after?: number;
 95	  /**
 96	   * Configuration options for a text response from the model. Can be plain text or
 97	   * structured JSON data. Learn more:
 98	   *
 99	   * - [Text inputs and outputs](https://platform.openai.com/docs/guides/text)
100	   * - [Structured Outputs](https://platform.openai.com/docs/guides/structured-outputs)
101	   */
102	  text?: ResponseTextConfig;
103	
104	  /**
105	   * An array of tools the model may call while generating a response. When continuing a stream, provide
106	   * the same tools as the original request.
107	   */
108	  tools?: ParseableToolsParams;
109	};
110	
111	/** Responses API events with normalized lifecycle output and snapshot-enhanced delta listeners. */
112	type ResponseEvents = BaseEvents &
113	  Omit<
114	    {
115	      [K in ResponseStreamEvent['type']]: (
116	        event: Extract<
117	          ResponseStreamEvent,
118	          {
119	            /** Event discriminator that selects the listener's precise server-event payload. */
120	            type: K;
121	          }
122	        >,
123	      ) => void;
124	    },
125	    'response.output_text.delta' | 'response.function_call_arguments.delta' | 'error'
126	  > & {
127	    /** Called for every supported response event that passes the replay sequence filter. */
128	    event: (event: ResponseStreamEvent) => void;
129	    /** Called with each text fragment and the complete text accumulated for its content part. */
130	    'response.output_text.delta': (event: ResponseTextDeltaEvent) => void;
131	    /** Called with each argument fragment and the complete JSON accumulated for its function call. */
132	    'response.function_call_arguments.delta': (event: ResponseFunctionCallArgumentsDeltaEvent) => void;
133	  };
134	
135	/** Response request parameters retained to parse structured output and tool arguments. */
136	export type ResponseStreamingParams = Omit<ResponseCreateParamsBase, 'stream'> & {
137	  /** Streaming is always enabled by the helper and may be specified explicitly. */
138	  stream?: true;
139	};
140	
141	/** Streams Responses API events while accumulating the latest response and parsed output. */
142	export class ResponseStream<ParsedT = null>
143	  extends EventStream<ResponseEvents>
144	  implements AsyncIterable<ResponseStreamEvent>
145	{
146	  #params: ResponseStreamingParams | null;
147	  #currentResponseSnapshot: Response | undefined;
148	  #finalResponse: ParsedResponse<ParsedT> | undefined;
149	  #accumulatorContext = createResponseContext();
150	  #outputPositions = new Map<number, number>();
151	  #wireByIdentity = new Map<string, number>();
152	  #interimOrderDirty = false;
153	  #completedOutput = new Map<number, Response['output'][number]>();
154	  #unfinishedOutput = new Map<number, string>();
155	
156	  /** Creates an unstarted stream, retaining request parameters for structured-output parsing. */
157	  constructor(params: ResponseStreamingParams | null) {
158	    super();
159	    this.#params = params;
160	    this.once('end', () => {
161	      this.#outputPositions.clear();
162	      this.#wireByIdentity.clear();
163	      this.#completedOutput.clear();
164	      this.#unfinishedOutput.clear();
165	    });
166	  }
167	
168	  /** Starts a new response stream or replays an existing response by its identifier. */
169	  static createResponse<ParsedT>(
170	    client: OpenAI,
171	    params: ResponseStreamParams,
172	    options?: ResponseParseOptions,
173	  ): ResponseStream<ParsedT> {
174	    const { getTextFormat, requestOptions } = resolveResponseParseOptions(params, options);
175	    const runner = new ResponseStream<ParsedT>(Array.isArray(params.tools) ? { tools: params.tools } : {});
176	    runner._run(() =>
177	      runner._createOrRetrieveResponse(
178	        client,
179	        params,
180	        {
181	          ...requestOptions,
182	          __metadata: { ...requestOptions?.__metadata, helperMethod: 'stream' },
183	        },
184	        getTextFormat,
185	      ),
186	    );
187	    return runner;
188	  }
189	
190	  /** Consumes serialized response events from a readable stream in another runtime. */
191	  static fromReadableStream(stream: ReadableStream): ResponseStream<null> {
192	    const runner = new ResponseStream(null);
193	    runner._run(() => runner._fromReadableStream(stream));
194	    return runner;
195	  }
196	
197	  #beginRequest() {
198	    if (this.ended) {
199	      return;
200	    }
201	    this.#currentResponseSnapshot = undefined;
202	    this.#accumulatorContext = createResponseContext();
203	    this.#outputPositions.clear();
204	    this.#wireByIdentity.clear();
205	    this.#interimOrderDirty = false;
206	    this.#completedOutput.clear();
207	    this.#unfinishedOutput.clear();
208	  }
209	
210	  #prepareEvent(event: ResponseStreamEvent): ResponseStreamEvent | null {
211	    if (
212	      event.type === 'response.created' ||
213	      event.type === 'response.queued' ||
214	      event.type === 'response.in_progress' ||
215	      event.type === 'response.completed' ||
216	      event.type === 'response.failed' ||
217	      event.type === 'response.incomplete'
218	    ) {
219	      if (!hasOwn(event, 'response')) {
220	        throw new OpenAIError('Lifecycle events require their own response field.');
221	      }
222	      const { response: wireResponse, ...fields } = event;
223	      if (!isObj(wireResponse)) {
224	        throw new OpenAIError('Lifecycle events require a response object.');
225	      }
226	      let response = structuredClone(wireResponse);
227	      if (this.#currentResponseSnapshot && response.id !== this.#currentResponseSnapshot.id) {
228	        throw new OpenAIError('Lifecycle response identity changed.');
229	      }
230	      if (!hasOwn(response, 'output') || response.output == null) {
231	        let output: Response['output'];
232	        if (event.type === 'response.completed') {
233	          output = [...this.#completedOutput]
234	            // oxlint-disable-next-line unicorn/no-array-sort -- Sort a fresh array; ES2020 declarations do not include toSorted.
235	            .sort(([left], [right]) => left - right)
236	            .map(([, item]) => structuredClone(item));
237	        } else if (event.type === 'response.failed' || event.type === 'response.incomplete') {
238	          output = [...this.#outputPositions.keys()]
239	            // oxlint-disable-next-line unicorn/no-array-sort -- Sort fresh wire indexes; retain partial and completed items.
240	            .sort((left, right) => left - right)
241	            .map((index) => structuredClone(this.#outputAtWireIndex(index)!));
242	        } else {
243	          output = [];
244	        }
245	        response = { ...response, output };
246	        if (
247	          event.type === 'response.completed' ||
248	          event.type === 'response.failed' ||
249	          event.type === 'response.incomplete'
250	        ) {
251	          addOutputText(response);
252	        }
253	      }
254	      if (event.type === 'response.completed') {
255	        this.#assertComplete(response);
256	      }
257	      return { ...fields, type: event.type, sequence_number: event.sequence_number, response };
258	    }
259	    return this.#prepareOutputEvent(event);
260	  }
261	
262	  #prepareOutputEvent(event: ResponseStreamEvent): ResponseStreamEvent | null {
263	    if (!this.#currentResponseSnapshot || !hasOwn(event, 'output_index') || !('output_index' in event)) {
264	      return event;
265	    }
266	    const index = event.output_index;
267	    if (!Number.isSafeInteger(index) || index < 0) {
268	      throw new OpenAIError('Invalid response output index.');
269	    }
270	    let position: number;
271	    if (event.type === 'response.output_item.added') {
272	      if (event.item == null) {
273	        return null;
274	      }
275	      if (this.#completedOutput.has(index) || this.#unfinishedOutput.has(index)) {
276	        throw new OpenAIError(`Duplicate response output index ${index}.`);
277	      }
278	      position = this.#currentResponseSnapshot.output.length;
279	    } else {
280	      const existing = this.#outputPositions.get(index);
281	      if (existing === undefined) {
282	        throw new OpenAIError(`missing output at index ${index}`);
283	      }
284	      position = existing;
285	    }
286	    return new Proxy(event, {
287	      get(target, property) {
288	        // oxlint-disable-next-line anti-slop/no-reflect-get -- Preserve the sanitized event fields and their receiver while translating only the dispatch index.
289	        return property === 'output_index' ? position : Reflect.get(target, property, target);
290	      },
291	    });
292	  }
293	
294	  #outputAtWireIndex(wireIndex: number): Response['output'][number] | undefined {
295	    const position = this.#outputPositions.get(wireIndex);
296	    return (
297	      this.#completedOutput.get(wireIndex) ??
298	      (position === undefined ? undefined : this.#currentResponseSnapshot?.output[position])
299	    );
300	  }
301	
302	  #assertComplete(response: Response): void {
303	    if (this.#unfinishedOutput.size === 0 && this.#completedOutput.size === 0) {
304	      return;
305	    }
306	    const finalItems = new Map((response.output ?? []).map((item) => [outputIdentity(item), item]));
307	    for (const item of this.#completedOutput.values()) {
308	      const replacement = finalItems.get(outputIdentity(item));
309	      if (replacement) {
310	        validateResponseOutputItemIdentity(item, replacement, 'response.completed');
311	      }
312	    }
313	    for (const [wireIndex, identity] of this.#unfinishedOutput) {
314	      const replacement = finalItems.get(identity);
315	      if (!replacement) {
316	        throw new OpenAIError('Cannot complete response with unfinished output items.');
317	      }
318	      const previous = this.#outputAtWireIndex(wireIndex);
319	      if (!previous) {
320	        throw new OpenAIError('Cannot complete response with a missing output identity.');
321	      }
322	      validateResponseOutputItemIdentity(previous, replacement, 'response.completed');
323	    }
324	  }
325	
326	  #recordOutput(event: ResponseStreamEvent, response: Response, position: number | undefined) {
327	    if (event.type === 'response.completed') {
328	      this.#interimOrderDirty = false;
329	      return;
330	    }
331	    if (response !== this.#currentResponseSnapshot) {
332	      const previous = new Map<string, number>();
333	      for (const [wireIndex, item] of this.#completedOutput) {
334	        previous.set(outputIdentity(item), wireIndex);
335	      }
336	      for (const [wireIndex, identity] of this.#unfinishedOutput) {
337	        previous.set(identity, wireIndex);
338	      }
339	      const positions = new Map<number, number>();
340	      this.#wireByIdentity.clear();
341	      for (const [newPosition, item] of response.output.entries()) {
342	        const identity = outputIdentity(item);
343	        const oldWireIndex = previous.get(identity);
344	        const wireIndex = oldWireIndex ?? newPosition;
345	        const done = this.#completedOutput.get(wireIndex);
346	        const unfinished = this.#unfinishedOutput.get(wireIndex);
347	        if (
348	          positions.has(wireIndex) ||
349	          (done && outputIdentity(done) !== identity) ||
350	          (unfinished !== undefined && unfinished !== identity)
351	        ) {
352	          throw new OpenAIError('Response snapshot has conflicting output positions.');
353	        }
354	        const previousItem = this.#outputAtWireIndex(wireIndex);
355	        if (previousItem) {
356	          validateResponseOutputItemIdentity(previousItem, item, event.type);
357	        }
358	        positions.set(wireIndex, newPosition);
359	        this.#wireByIdentity.set(identity, wireIndex);
360	        if (done) {
361	          this.#completedOutput.set(wireIndex, structuredClone(item));
362	        } else {
363	          this.#unfinishedOutput.set(wireIndex, identity);
364	        }
365	      }
366	      this.#outputPositions = positions;
367	      this.#interimOrderDirty = !['response.failed', 'response.incomplete'].includes(event.type);
368	      if (['response.created', 'response.queued', 'response.in_progress'].includes(event.type)) {
369	        this.#reorderInterimOutput(response);
370	      }
371	      return;
372	    }
373	    if (position === undefined) {
374	      return;
375	    }
376	    if (event.type === 'response.output_item.added' && event.item != null) {
377	      this.#outputPositions.set(event.output_index, position);
378	      const identity = outputIdentity(event.item);
379	      this.#unfinishedOutput.set(event.output_index, identity);
380	      this.#wireByIdentity.set(identity, event.output_index);
381	      this.#interimOrderDirty = true;
382	    } else if (event.type === 'response.output_item.done') {
383	      const item = response.output[position];
384	      if (!item) {
385	        throw new OpenAIError(`missing output at index ${event.output_index}`);
386	      }
387	      this.#completedOutput.set(event.output_index, structuredClone(item));
388	      this.#unfinishedOutput.delete(event.output_index);
389	    }
390	  }
391	
392	  #reorderInterimOutput(response: Response) {
393	    if (!this.#interimOrderDirty) {
394	      return;
395	    }
396	    const ordered = [...this.#outputPositions];
397	    // oxlint-disable-next-line unicorn/no-array-sort -- Sort the fresh map entries; the source supports ES2020.
398	    ordered.sort(([left], [right]) => left - right);
399	    if (ordered.some(([, oldPosition], newPosition) => oldPosition !== newPosition)) {
400	      const derivedText = this.#accumulatorContext.canonicalSnapshot === response;
401	      response.output = ordered.map(([, oldPosition]) => response.output[oldPosition]!);
402	      this.#outputPositions = new Map(ordered.map(([wireIndex], newPosition) => [wireIndex, newPosition]));
403	      this.#accumulatorContext = createResponseContext();
404	      if (derivedText) {
405	        ensureCanonicalOutputText(this.#accumulatorContext, response);
406	      }
407	    }
408	    this.#interimOrderDirty = false;
409	  }
410	
411	  #updateInterimResponse(incoming: Response, snapshot: Response): boolean {
412	    if (!Array.isArray(incoming.output)) {
413	      return false;
414	    }
415	    const suppliedText = hasOwn(incoming, 'output_text') ? incoming.output_text : undefined;
416	    if (incoming.output.length !== 0) {
417	      // The temporary response validates only the supplied items. Its derived
418	      // output_text is not the aggregate for the retained full response.
419	      const validated = cloneValidatedResponse(createResponseContext(), incoming);
420	      const replacements: { wire: number; position: number; item: Response['output'][number] }[] = [];
421	      for (const item of validated.output) {
422	        const wire = this.#wireByIdentity.get(outputIdentity(item));
423	        const position = wire === undefined ? undefined : this.#outputPositions.get(wire);
424	        if (wire === undefined || position === undefined) {
425	          return false;
426	        }
427	        replacements.push({ wire, position, item });
428	      }
429	      const updateText = suppliedText == null;
430	      if (!updateText) {
431	        // Explicit interim text replaces the full aggregate after any required
432	        // reorder; deriving text from retained messages here would be discarded.
433	        this.#accumulatorContext.canonicalSnapshot = undefined;
434	      }
435	      for (const { wire, position, item } of replacements) {
436	        replaceResponseOutputItem(this.#accumulatorContext, snapshot, position, item, updateText);
437	        if (this.#completedOutput.has(wire)) {
438	          this.#completedOutput.set(wire, structuredClone(item));
439	        }
440	      }
441	      this.#reorderInterimOutput(snapshot);
442	    }
443	    const { output } = snapshot;
444	    let outputText = suppliedText;
445	    if (outputText == null) {
446	      ensureCanonicalOutputText(this.#accumulatorContext, snapshot);
447	      outputText = snapshot.output_text;
448	    } else {
449	      this.#accumulatorContext.canonicalSnapshot = undefined;
450	    }
451	    for (const key of Object.keys(snapshot)) {
452	      if (!hasOwn(incoming, key)) {
453	        Reflect.deleteProperty(snapshot, key);
454	      }
455	    }
456	    Object.defineProperties(
457	      snapshot,
458	      Object.getOwnPropertyDescriptors({ ...incoming, output, output_text: outputText }),
459	    );
460	    return true;
461	  }
462	
463	  // oxlint-disable-next-line complexity -- Accumulate one native event, preserve admitted routing fields, then dispatch its matching enriched event.
464	  #addEvent(this: ResponseStream<ParsedT>, event: ResponseStreamEvent, starting_after: number | null) {
465	    if (this.ended) {
466	      return;
467	    }
468	
469	    const maybeEmit = (name: string, event: ResponseStreamEvent & { snapshot?: string }) => {
470	      if (starting_after == null || event.sequence_number > starting_after) {
471	        // SAFETY: The caller derives the event name from the dispatched event discriminator; this bridge preserves the corresponding payload.
472	        this._emit(name as any, event);
473	      }
474	    };
475	
476	    if (event.type === 'error') {
477	      // First-party providers nest their error payload; retain flat compatibility for
478	      // serialized events matching the currently published event schema.
479	      const error =
480	        // oxlint-disable-next-line anti-slop/no-runtime-typeof -- An error event can contain malformed server data; validate its container before extracting error
481	        'error' in event && typeof event.error === 'object' && event.error !== null ? event.error : event;
482	      throw new APIError(undefined, error, event.message, undefined);
483	    }
484	
485	    let dispatchEvent: ResponseStreamEvent = event;
486	    let outputPosition: number | undefined;
487	    const response = accumulateResponseWithContext(
488	      event,
489	      this.#currentResponseSnapshot,
490	      this.#accumulatorContext,
491	      true,
492	      (sanitizedEvent) => {
493	        dispatchEvent = sanitizedEvent;
494	        const prepared = this.#prepareEvent(sanitizedEvent);
495	        if (prepared) {
496	          if (hasOwn(prepared, 'output_index') && 'output_index' in prepared) {
497	            outputPosition = prepared.output_index;
498	          } else if (hasOwn(prepared, 'response') && 'response' in prepared) {
499	            dispatchEvent = prepared;
500	            if (
501	              (prepared.type === 'response.created' ||
502	                prepared.type === 'response.queued' ||
503	                prepared.type === 'response.in_progress') &&
504	              this.#currentResponseSnapshot
505	            ) {
506	              if (this.#updateInterimResponse(prepared.response, this.#currentResponseSnapshot)) {
507	                return null;
508	              }
509	              const identities = new Set(prepared.response.output.map(outputIdentity));
510	              const retained = this.#currentResponseSnapshot.output.filter(
511	                (item) => !identities.has(outputIdentity(item)),
512	              );
513	              if (retained.length) {
514	                return {
515	                  ...prepared,
516	                  response: { ...prepared.response, output: [...prepared.response.output, ...retained] },
517	                };
518	              }
519	            }
520	          }
521	        }
522	        return prepared;
523	      },
524	    );
525	    this.#recordOutput(dispatchEvent, response, outputPosition);
526	    this.#currentResponseSnapshot = response;
527	    if (dispatchEvent.type === 'response.output_item.added' && dispatchEvent.item == null) {
528	      return;
529	    }
530	    const wireSnapshot = { ...dispatchEvent };
531	    for (const key of Object.keys(nativeEventFields)) {
532	      const descriptor = Object.getOwnPropertyDescriptor(dispatchEvent, key);
533	      if (descriptor && !descriptor.enumerable) {
534	        Object.defineProperty(wireSnapshot, key, {
535	          // oxlint-disable-next-line anti-slop/no-reflect-get -- Read accepted non-enumerable fields from the sanitized Proxy, never the original transport.
536	          value: Reflect.get(dispatchEvent, key, dispatchEvent),
537	          enumerable: true,
538	        });
539	      }
540	    }
541	    const eventSnapshot = structuredClone(wireSnapshot);
542	    maybeEmit('event', eventSnapshot);
543	
544	    switch (wireSnapshot.type) {
545	      case 'response.output_text.delta': {
546	        const output = response.output[outputPosition ?? wireSnapshot.output_index];
547	        if (!output) {
548	          throw new OpenAIError(`missing output at index ${wireSnapshot.output_index}`);
549	        }
550	        if (output.type === 'message') {
551	          const content = output.content[wireSnapshot.content_index];
552	          if (!content) {
553	            throw new OpenAIError(`missing content at index ${wireSnapshot.content_index}`);
554	          }
555	          if (content.type !== 'output_text') {
556	            throw new OpenAIError(`expected content to be 'output_text', got ${content.type}`);
557	          }
558	
559	          maybeEmit('response.output_text.delta', {
560	            ...structuredClone(wireSnapshot),
561	            snapshot: content.text,
562	          });
563	        }
564	        break;
565	      }
566	      case 'response.function_call_arguments.delta': {
567	        const output = response.output[outputPosition ?? wireSnapshot.output_index];
568	        if (!output) {
569	          throw new OpenAIError(`missing output at index ${wireSnapshot.output_index}`);
570	        }
571	        if (output.type === 'function_call') {
572	          maybeEmit('response.function_call_arguments.delta', {
573	            ...structuredClone(wireSnapshot),
574	            snapshot: output.arguments,
575	          });
576	        }
577	        break;
578	      }
579	      default: {
580	        maybeEmit(wireSnapshot.type, eventSnapshot);
581	        break;
582	      }
583	    }
584	  }
585	
586	  #endRequest(format?: ResponseParserTextFormat): ParsedResponse<ParsedT> {
587	    if (this.ended) {
588	      throw new OpenAIError(`stream has ended, this shouldn't happen`);
589	    }
590	    const snapshot = this.#currentResponseSnapshot;
591	    if (!snapshot) {
592	      throw new OpenAIError(`request ended without sending any events`);
593	    }
594	    this.#reorderInterimOutput(snapshot);
595	    this.#currentResponseSnapshot = undefined;
596	    this.#accumulatorContext = createResponseContext();
